const $=s=>document.querySelector(s);let state;try{state=JSON.parse(localStorage.getItem('nhiphoc-demo'))}catch{}state=Object.assign({moved:false,quiz:false,files:[],messages:[],tele:[]},state||{});let page='home';const save=()=>{try{localStorage.setItem('nhiphoc-demo',JSON.stringify(state))}catch{}};const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));function toast(t){$('#toast').textContent=t;$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',3200)}
const titles={home:'Hôm nay',learn:'Phòng học',path:'Lộ trình của tôi',library:'Tài liệu',schedule:'Lịch học'};
const intro=(eyebrow,title,sub,right='')=>`<section class="intro"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p class="muted">${sub}</p></div>${right}</section>`;
const days=()=>`<div class="week">${['T2|9','T3|10','T4|11','T5|12','T6|13','T7|14','CN|15'].map((d,i)=>`<div class="day ${i===3?'today':''}">${d.split('|')[0]}<b>${d.split('|')[1]}</b><i></i></div>`).join('')}</div>`;
function agenda(){return `<div class="agenda"><div class="time">20:00</div><div class="detail"><h4>Biến cố & xác suất</h4><p>${state.moved?'Thứ Sáu, 13/11':'Hôm nay'} · 30 phút · Cùng gia sư</p></div><span class="pill">${state.moved?'Đã dời':'Sắp tới'}</span></div><div class="agenda"><div class="time">20:30</div><div class="detail"><h4>Ôn lại quy tắc đếm</h4><p>${state.moved?'Thứ Sáu, 13/11':'Hôm nay'} · 10 phút · 5 câu hỏi</p></div></div>`}
function telehead(){return `<div class="telehead"><div class="telelogo">➤</div><div><strong>Nhịp học trên Telegram</strong><div class="live"><i></i> Mô phỏng · chưa kết nối bot thật</div></div></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$('#crumb').innerHTML=`Không gian học tập <b>/</b> ${titles[page]}`;$('#fileCount').textContent=3+state.files.length;const c=$('#content');
if(page==='home')c.innerHTML=intro('THỨ NĂM, 12 THÁNG 11','Chào Minh, học một chút nhé <span style="color:#92a77c">✳</span>','Mỗi ngày một chút. Kiến thức sẽ ở lại lâu hơn.','<div class="streak">☀ &nbsp; 4 ngày giữ nhịp</div>')+`<div class="layout"><section><div class="hero"><div class="tag">TIẾP TỤC HÀNH TRÌNH &nbsp; / &nbsp; CHƯƠNG 02</div><h2>Từ sự ngẫu nhiên,<br>tìm ra quy luật.</h2><p>Cùng tìm hiểu biến cố và xác suất qua những ví dụ thật gần gũi.</p><button class="primary" data-go="learn">Vào học cùng gia sư <span>↗</span></button><div class="hero-art" aria-hidden="true"><span>⅙</span></div></div><div class="rowtitle"><h3>Một chút luyện tập</h3><span class="muted">Dành riêng cho bạn</span></div><div class="cards"><div class="card"><div class="icon">✎</div><h3>Thử sức, không áp lực</h3><p>Kiểm tra nhanh kiến thức vừa học.<br>Sai một chút, hiểu thêm một chút.</p><button data-quiz>${state.quiz?'Làm lại câu hỏi':'Làm quiz nhanh'} &nbsp; →</button></div><div class="card"><div class="icon">⌁</div><h3>Vì sao lại như vậy?</h3><p>“Hai biến cố độc lập có thể<br>xảy ra cùng lúc không?”</p><button data-discuss>Trao đổi với gia sư &nbsp; →</button></div></div><div class="rowtitle"><h3>Hành trình của bạn</h3><button class="textbutton" data-go="path">Xem lộ trình ↗</button></div><div class="panel journey"><span class="round">◒</span><div><strong>Xác suất & thống kê</strong><p>Đã đi được 38% chặng đường · Cứ từ từ, bạn làm tốt lắm.</p><div class="bar"><i style="width:38%"></i></div></div><span>↗</span></div></section><aside><div class="panel"><div class="panelhead"><h3>Nhịp học tuần này</h3><span>Tháng 11 &nbsp;⌄</span></div>${days()}${agenda()}<button class="textbutton" style="margin-top:10px" data-go="schedule">Bận rồi? Cùng sắp xếp lại →</button></div><div class="telegram">${telehead()}<div class="bubble">${state.moved?'Đã chuyển buổi học sang tối mai, 20:00. Lịch ôn cũng được dời theo. 🌿':'Tối nay mình có hẹn học lúc 20:00 nhé 🌿 Nếu bận, cứ nhắn mình đổi lịch.'}<time>Nhịp học · 18:00</time></div><button data-go="schedule">Thử nhắn “Nay tao bận” &nbsp; ↗</button></div><div class="tip"><strong>✧ &nbsp; Gia sư ghi nhớ</strong><br>Bạn hiểu tốt hơn khi có ví dụ trực quan. Buổi hôm nay mình sẽ bắt đầu bằng một trò tung xúc xắc.</div></aside></div>`;
if(page==='learn'){c.innerHTML=intro('PHÒNG HỌC · CHƯƠNG 02','Hiểu đến nơi, hỏi đến cùng.','Cứ đặt câu hỏi, phản biện hoặc thử một cách giải khác.')+`<div class="chatlayout"><div class="panel chatwindow"><div class="panelhead"><h3>✧ Gia sư của Minh</h3><span class="label">Trao đổi mẫu</span></div><div class="chatmessages" id="chatmessages"><div class="message"><small>GIA SƯ · DỰA TRÊN TÀI LIỆU CỦA BẠN</small>Hôm trước bạn đã ôn quy tắc đếm. Hôm nay mình thử dùng nó để hiểu xác suất nhé.<br><br>Tung một xúc xắc cân đối: có 6 kết quả có thể xảy ra. Theo bạn, xác suất ra số chẵn là bao nhiêu? Vì sao?<div class="ref">▤ Giáo trình Xác suất · Chương 2 · Tài liệu minh họa</div></div>${state.messages.map(m=>`<div class="message ${m.role==='user'?'mine':''}"><small>${m.role==='user'?'BẠN':'GIA SƯ · PHẢN HỒI MẪU'}</small>${esc(m.text)}</div>`).join('')}</div><div class="suggestions"><button data-prompt="Tao nghĩ là 1/2 vì có 3 số chẵn">Thử trả lời</button><button data-prompt="Hai biến cố độc lập có xảy ra cùng lúc không?">Phản biện một chút</button><button data-quiz>Tạo quiz bài này</button></div><form class="chatform" id="studyform"><input aria-label="Tin nhắn cho gia sư" placeholder="Nói cách bạn hiểu, hoặc hỏi bất cứ điều gì…" required><button class="primary" aria-label="Gửi">↑</button></form></div><aside class="panel"><div class="eyebrow">BUỔI HỌC CỦA BẠN</div><h2>Biến cố & xác suất</h2><p class="muted">◷ 30 phút · Bài 2.1</p><div class="lesson"><span>✓</span><h3>Nhắc lại quy tắc đếm</h3></div><div class="lesson"><span>◉</span><h3>Hiểu qua ví dụ</h3></div><div class="lesson"><span>○</span><h3>Thử sức với quiz</h3></div><div class="tip" style="display:block;padding:0">✧ Hồ sơ ghi nhớ<br>Bạn thích ví dụ trực quan và cần luyện thêm cách phân biệt độc lập với xung khắc.</div><button class="secondary full" style="margin-top:25px" data-go="library">▤ Xem tài liệu buổi học</button></aside></div>`;$('#studyform').onsubmit=e=>{e.preventDefault();study(e.target.querySelector('input').value)};$('#chatmessages').scrollTop=99999;}
if(page==='path')c.innerHTML=intro('LỘ TRÌNH CỦA TÔI','Một đường đi, có thể đổi hướng.','Mục tiêu: hiểu nền tảng xác suất để đọc và phân tích dữ liệu.')+`<div class="panel"><div class="panelhead"><h3>Xác suất & thống kê</h3><span class="label">6 chương · 8 tuần dự kiến</span></div><p class="muted">Dựa trên giáo trình của bạn · 3 buổi / tuần · 30 phút / buổi</p><div class="bar"><i style="width:38%"></i></div>${['Nền tảng & quy tắc đếm','Biến cố & xác suất','Xác suất có điều kiện & Bayes','Biến ngẫu nhiên','Các phân phối thường gặp','Ước lượng & kiểm định'].map((x,i)=>`<div class="lesson"><span class="num">${i===0?'✓':String(i+1).padStart(2,'0')}</span><div><h3>${x}</h3><p>${i===0?'Đã hoàn thành · Ôn lại khi cần':i===1?'Đang học · Cần luyện thêm phân biệt biến cố': 'Sắp tới · Học sau phần kiến thức nền'}</p></div><button class="${i===1?'primary':'secondary'}" data-go="learn">${i===0?'Ôn lại':i===1?'Tiếp tục':'Khám phá'} →</button></div>`).join('')}</div><div class="panel widepanel"><h3>✧ Hướng tìm hiểu thêm</h3><p class="muted">Vì sao xét nghiệm dương tính chưa chắc đã có bệnh? Định lý Bayes sẽ giúp bạn giải thích.</p><button class="textbutton" data-prompt="Tao muốn tìm hiểu thêm về định lý Bayes">Cùng gia sư khám phá →</button></div>`;
if(page==='library'){c.innerHTML=intro('THƯ VIỆN CỦA BẠN','Kiến thức bắt đầu từ đây.','Tài liệu là điểm tựa. Câu hỏi của bạn mở thêm những hướng đi.')+`<div class="panel"><div class="panelhead"><h3>Tài liệu môn Xác suất & thống kê</h3><span class="label">${3+state.files.length} tài liệu</span></div>${['Giáo trình Xác suất thống kê.pdf','Bài giảng 02 — Biến cố và xác suất.pdf','Ghi chú — Quy tắc đếm.md',...state.files].map((f,i)=>`<div class="file"><span class="fileicon">${i===2?'MD':'PDF'}</span><div><h3>${esc(f)}</h3><small>${i<3?'Tài liệu mẫu · Dùng minh họa giao diện':'Đã chọn trên máy · Chưa phân tích nội dung'}</small></div></div>`).join('')}<div class="upload"><label>↥ &nbsp; Thêm tài liệu của bạn<input id="upload" type="file" multiple accept=".pdf,.txt,.md,.docx,.pptx"><p class="muted">PDF, DOCX, PPTX, TXT · Bản thử chỉ lưu tên tệp</p></label></div></div>`;$('#upload').onchange=e=>{state.files.push(...Array.from(e.target.files).map(f=>f.name));save();render();toast('Đã thêm tên tài liệu. Bản thử chưa đọc nội dung tệp.')}}
if(page==='schedule'){c.innerHTML=intro('KẾ HOẠCH LINH HOẠT','Lịch học đi cùng cuộc sống.','Bận một buổi cũng không sao. Cùng tìm một nhịp phù hợp hơn.')+`<div class="schedulegrid"><div class="panel"><div class="panelhead"><h3>Tuần 09 — 15 tháng 11</h3><span class="label">Giờ Việt Nam</span></div>${days()}${agenda()}<div class="agenda"><div class="time">09:00</div><div class="detail"><h4>Quiz tổng hợp chương 2</h4><p>Chủ nhật, 15/11 · 15 phút</p></div></div><p class="ref">✧ Bạn thường học hiệu quả vào 20:00. Khi đổi lịch, mình giữ mỗi buổi tối đa 45 phút.</p><button class="secondary full" id="restore">Khôi phục lịch mẫu</button></div><div class="telegram">${telehead()}<div class="telechat" id="telechat"><div class="bubble">Tối nay 20:00 mình học Biến cố & xác suất trong 30 phút nhé. Có cần điều chỉnh gì không?<time>18:00</time></div>${state.tele.map(m=>`<div class="bubble ${m.role==='user'?'user':''}">${esc(m.text)}</div>`).join('')}</div><div class="suggestions"><button data-tele="Nay tao bận, mai học lúc 20h nhé">Mai học nhé</button><button data-tele="Hôm nay chỉ học 15 phút thôi">Học nhẹ 15 phút</button></div><form class="chatform" id="teleform"><input aria-label="Nhắn cho bot Telegram giả lập" placeholder="Nhắn bot để sắp xếp lại…" required><button class="primary" aria-label="Gửi tin nhắn Telegram">➤</button></form><p class="muted" style="font-size:9px">Mô phỏng dời sang mai / học nhẹ / lùi 30 phút.<br>Chưa gửi tin nhắn hoặc tạo lịch thật.</p></div></div>`;$('#teleform').onsubmit=e=>{e.preventDefault();tele(e.target.querySelector('input').value)};$('#restore').onclick=()=>{state.moved=false;state.tele=[];save();render();toast('Đã khôi phục lịch mẫu')};$('#telechat').scrollTop=99999;}
bind();}
function go(p){page=p;location.hash=p;render();window.scrollTo(0,0)}function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-quiz]').forEach(b=>b.onclick=quiz);document.querySelectorAll('[data-prompt]').forEach(b=>b.onclick=()=>{const v=b.dataset.prompt;go('learn');study(v)});document.querySelectorAll('[data-discuss]').forEach(b=>b.onclick=()=>{go('learn');study('Hai biến cố độc lập có xảy ra cùng lúc không?')});document.querySelectorAll('[data-tele]').forEach(b=>b.onclick=()=>tele(b.dataset.tele))}
function study(input){const t=input.trim();if(!t)return;let reply;if(/độc lập|phản biện|xung khắc/i.test(t))reply='Có nhé. “Độc lập” nghĩa là biết biến cố A xảy ra không làm thay đổi xác suất của B. Chẳng hạn tung hai đồng xu: đồng thứ nhất ngửa và đồng thứ hai ngửa có thể cùng xảy ra, với xác suất 1/4. “Xung khắc” mới là không thể cùng xảy ra. Bạn thử lấy một ví dụ xung khắc xem?';else if(/bayes/i.test(t))reply='Mình thử bắt đầu bằng câu hỏi này: một bệnh rất hiếm, xét nghiệm khá chính xác, vậy kết quả dương tính có đủ kết luận mắc bệnh không? Để tính được, ta còn cần tỉ lệ mắc bệnh ban đầu và tỉ lệ dương tính giả. Bạn muốn tự thử một ví dụ 1.000 người trước không?';else if(/1\/2|50|số chẵn/i.test(t))reply='Đúng hướng rồi: 3 kết quả thuận lợi trên 6 kết quả đồng khả năng, nên xác suất là 1/2. Điểm quan trọng là “đồng khả năng”. Nếu xúc xắc bị lệch, cách đếm này còn đúng không?';else reply='Trong bản thử, đây là phản hồi mẫu để bạn hình dung cách trao đổi. Khi nối AI thật, gia sư sẽ đọc tài liệu và hồ sơ học của bạn. Thử tiếp: bạn có thể giải thích ý vừa nói bằng một ví dụ cụ thể không? Mình sẽ cùng kiểm tra giả định và tìm phản ví dụ.';state.messages.push({role:'user',text:t},{role:'assistant',text:reply});save();render()}
function tele(input){const t=input.trim();if(!t)return;let r;if(/mai|ngày mai/i.test(t)){state.moved=true;r='Được nhé 🌿 Mình chuyển buổi học sang thứ Sáu 13/11 lúc 20:00, lịch ôn sang 20:30. Không trùng buổi nào trong lịch mẫu. Tối nay bạn nghỉ nhé!';}else if(/15|nhẹ|ít thời gian/i.test(t)){r='Mình đề xuất buổi nhẹ 15 phút: ôn 5 phút + quiz 10 phút. Phần kiến thức mới chuyển sang buổi sau. Đây là đề xuất mẫu; lịch bên trái hiện vẫn giữ thời lượng cũ.';}else if(/30|nửa tiếng/i.test(t)){r='Nếu lùi 30 phút, buổi học sẽ là 20:30 và ôn lúc 21:00. Đây là đề xuất mẫu; bạn có thể thử nút “Mai học nhé” để xem lịch cập nhật trực tiếp.';}else r='Bạn muốn dời sang ngày nào, lúc mấy giờ? Bản thử hiểu được “mai học lúc 20h”, “học nhẹ 15 phút” và “lùi 30 phút”.';state.tele.push({role:'user',text:t},{role:'assistant',text:r});save();render();if(state.moved)toast('Lịch mẫu đã cập nhật · Thứ Sáu, 20:00')}
function quiz(){$('#feedback').textContent='';$('#answers').innerHTML=['1/2','1/3','1/8','3/8'].map(a=>`<button>${a}</button>`).join('');$('#answers').querySelectorAll('button').forEach(b=>b.onclick=()=>{const right=b.textContent==='1/8';b.classList.add(right?'correct':'wrong');$('#feedback').textContent=right?'Chính xác! Ba lần tung độc lập: 1/2 × 1/2 × 1/2 = 1/8. Kết quả đã được lưu trong bản thử.':'Thử lại nhé: mỗi lần ngửa có xác suất 1/2. Ba lần độc lập thì ta nhân ba xác suất với nhau.';if(right){state.quiz=true;save()}});$('#quiz').showModal()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>go(b.dataset.page));$('#reset').onclick=()=>{if(confirm('Đặt lại toàn bộ dữ liệu của bản thử?')){localStorage.removeItem('nhiphoc-demo');location.reload()}};window.addEventListener('hashchange',()=>{let p=location.hash.slice(1);if(titles[p]&&page!==p){page=p;render()}});page=titles[location.hash.slice(1)]?location.hash.slice(1):'home';render();
